#!/usr/bin/env bash
# ============================================================================
# VideoMind, Part 14e: Insights and Costs in the admin dashboard
# ============================================================================
# FOR THE rebuild BRANCH. It refuses to run on main: apply it on rebuild,
# check it, then fast forward main.
#
# After this part, Insights and Costs in the dashboard are live:
#   Insights
#   * daily series across the site: views, watch time, new wallets, uploads,
#     minutes transcribed, AI tokens, live events; over 7 days, 28 days,
#     90 days or 12 months, compared with the period before; Show the numbers
#   * use by feature, and the most watched videos
#   * the audit log: every admin sign in and action, filters, older entries
#   Costs
#   * an estimate per month from the usage ledger: by service, by feature,
#     and the wallets that cost the most
#   * a price table seeded from each provider's official pricing page on
#     15 Oct 2026 (Claude Sonnet 5.5 and Haiku 5.5, whisper-1,
#     gpt-live-transcribe, text-embedding-3-small, Cloudflare R2), editable,
#     with links to the sources
#   * fixed monthly costs you add (Render, Vercel, Turso, LiveKit and so on)
#   * price changes and fixed costs are written to the audit log
#
#   BACKEND    2 new files, 2 changed. Migration 022 (two new tables, one
#              index; runs by itself when the API starts)
#   DASHBOARD  3 new files, 3 changed. No packages
#
#   ./vm_insights.sh            apply (needs Part 14d on the branch)
#   ./vm_insights.sh --force    apply even if local files differ from GitHub
#   ./vm_insights.sh --revert   restore everything from the latest backup
#
# Run from the repo root (dir containing backend/ and frontend/).
# ============================================================================
set -euo pipefail

MARKER="vm_insights"
STAMP="$(date +%Y%m%d-%H%M%S)"
BAKDIR=".vm_insights_backups"

ADD=(
  "backend/src/lib/adminInsights.ts"
  "backend/src/lib/costs.ts"
  "dashboard/src/lib/actions.ts"
  "dashboard/src/app/(admin)/insights/page.tsx"
  "dashboard/src/app/(admin)/costs/page.tsx"
)
MOD=(
  "backend/src/routes/admin.ts"
  "backend/src/lib/migrations.ts"
  "dashboard/src/lib/api.ts"
  "dashboard/src/components/Shell.tsx"
  "dashboard/src/app/(admin)/page.tsx"
)
PRE_MOD=(
  "9e804d6432182b710d88c4603468964ea0612287df576ac7868d1978346c3cc9"
  "0fd564bd78eabb29bc3d886eb91fa0d41401ed4d9cfe245e02d09c904ce2585f"
  "2e8819b999a5d2eab057f4023e324f98dbc31639ca3f114f86bec2c7945f447c"
  "f174f8696921076b270ed5465bb18b535cefa62cd321ef1288911d452d250a01"
  "18e0eb80c19522ecb0487a3ce6b0aa7b3a2992d36d7c9214a0699b34378f4f0e"
)
NEW_MOD=(
  "8f0d94eafc93b19c7e728203a8f8b836b62e6357f66c66fae77548c664247163"
  "ca2f10805537e7648368d9d9c1bb5bca49592eb78cdf7246f9dc62d2d49ff736"
  "a81e17141e0e7302384725e61a68564d153c34d6323a3a6b2f32e79850b1cdf2"
  "3d0e7b127f2b32e558b8070454c3bd6ff7fbcbf1bd3e4eb1c6b006ea59e62bcc"
  "efee9b5132ba0c66fa4713f7809366e0ef9d14f16d8f98d74108ca93378a763d"
)
NEW_ADD=(
  "dfcf6bbac361a55a09dd0834e3cea7ff8d65b91181e3f8019f2462e20d6bfbda"
  "0648569a094c249ecf6f00e5dbb62ddf8a52c40ff1165be386a6381acbd462e4"
  "de2ca13e961fcc5c1c9212f1dd4e76fb10a5a4a0a66b3ffedc1c2531ecfca2d9"
  "e4413acd6015a5aef04d81f725e9b6f8b55118f796f80f88bb507d3322062fa4"
  "cf31ffe621efe93b241411b493c875a506876cb8cfff74e572e9f463de6b638f"
)

say() { printf '  %s\n' "$1"; }
die() { printf 'ERROR: %s\n' "$1" >&2; exit 1; }
sha() {
  if command -v sha256sum >/dev/null 2>&1; then sha256sum "$1" | cut -d' ' -f1
  else shasum -a 256 "$1" | cut -d' ' -f1; fi
}
bname() { printf '%s' "$1" | sed 's#/#__#g'; }

[ -d frontend ] && [ -d backend ] || die "Run from repo root (dir with backend/ and frontend/)."

BRANCH="$(git rev-parse --abbrev-ref HEAD 2>/dev/null || true)"
if [ "$BRANCH" = "main" ]; then
  die "You are on main. This part is for the rebuild branch. Run: git checkout rebuild"
fi

restore_from() {
  local f
  for f in "${MOD[@]}"; do
    if [ -f "$1/$(bname "$f")" ]; then mkdir -p "$(dirname "$f")"; cp "$1/$(bname "$f")" "$f"; fi
  done
  for f in "${ADD[@]}"; do
    if [ -f "$1/$(bname "$f")" ]; then cp "$1/$(bname "$f")" "$f"; else rm -f "$f"; fi
  done
  # Folders this part made, once empty, go too.
  for f in "${ADD[@]}"; do
    d="$(dirname "$f")"
    while [ "$d" != "." ] && [ "$d" != "/" ] && rmdir "$d" 2>/dev/null; do d="$(dirname "$d")"; done
  done
}

if [ "${1:-}" = "--revert" ]; then
  [ -d "$BAKDIR" ] || die "No backup dir. Nothing to revert."
  LATEST="$(ls -1d "$BAKDIR"/*/ 2>/dev/null | sort | tail -1)"
  [ -n "$LATEST" ] || die "No backups found."
  restore_from "${LATEST%/}"
  say "Restored ${#MOD[@]} changed files and removed ${#ADD[@]} new files, from $LATEST"
  exit 0
fi

FORCE=0
[ "${1:-}" = "--force" ] && FORCE=1

if [ -f "${ADD[0]}" ] && grep -q "$MARKER" "${ADD[0]}" && grep -q "adminInsights" "backend/src/routes/admin.ts"; then
  say "Already applied ($MARKER marker present). Use --revert to undo."
  exit 0
fi

grep -q "adminOps" backend/src/routes/admin.ts 2>/dev/null || die "Part 14d is not on this branch. Run: git pull origin rebuild"

# ---- pre image check: every file must match what this part was built on ----
check_pre() {
  [ -f "$1" ] || die "$1 not found. Nothing changed."
  if [ "$(sha "$1")" != "$2" ]; then
    if [ "$FORCE" = "1" ]; then say "WARNING: $1 differs from GitHub rebuild (52c7ef0). Proceeding (--force)."
    else die "$1 differs from the version this part was built on (GitHub rebuild (52c7ef0)). Nothing changed. Run git pull origin rebuild, push or stash local edits, or run again with --force."; fi
  fi
}
i=0; for f in "${MOD[@]}"; do check_pre "$f" "${PRE_MOD[$i]}"; i=$((i+1)); done
i=0; for f in "${ADD[@]}"; do
  # A file already there with exactly this part's content is fine.
  if [ -f "$f" ] && [ "$FORCE" != "1" ] && [ "$(sha "$f")" != "${NEW_ADD[$i]}" ]; then die "$f already exists but is not this part's version. Nothing changed. Run again with --force to overwrite it."; fi
  i=$((i+1))
done

# ---- decode + verify every payload BEFORE touching anything ----
TMPD="$(mktemp -d)"
trap 'rm -rf "$TMPD"' EXIT
verify() {
  [ -s "$1" ] || die "$3: base64 decode produced an empty file. Nothing written."
  [ "$(sha "$1")" = "$2" ] || die "$3: payload checksum mismatch (script was corrupted in transit). Nothing written."
}

