B64_A4
verify "$TMPD/a4" "${NEW_ADD[4]}" "dashboard/src/app/(admin)/costs/page.tsx"

grep -q "$MARKER" "$TMPD/a0"                                   || die "adminInsights.ts payload missing marker. Aborting."
grep -q 'export async function auditLog' "$TMPD/a0"              || die "adminInsights.ts payload is wrong. Aborting."
grep -q 'export async function monthReport' "$TMPD/a1"           || die "costs.ts payload is wrong. Aborting."
grep -q 'export const featureLabel' "$TMPD/a2"                   || die "actions.ts payload is wrong. Aborting."
grep -q 'Show older entries' "$TMPD/a3"                          || die "insights page payload is wrong. Aborting."
grep -q 'Fixed monthly costs' "$TMPD/a4"                         || die "costs page payload is wrong. Aborting."
grep -q 'adminInsights' "$TMPD/m0"                   || die "routes/admin.ts payload is wrong. Aborting."
grep -q 'adminOps' "$TMPD/m0"                        || die "routes/admin.ts payload lost 14d. Aborting."
grep -q '022_costs' "$TMPD/m1"                     || die "migrations.ts payload is wrong. Aborting."
grep -q '021_removals' "$TMPD/m1"                  || die "migrations.ts payload lost 14c. Aborting."
grep -q 'export const getCosts' "$TMPD/m2"              || die "dashboard api.ts payload is wrong. Aborting."
grep -q 'export const getSecurity' "$TMPD/m2"           || die "dashboard api.ts payload lost 14d. Aborting."
grep -q 'href: "/costs"' "$TMPD/m3"           || die "Shell.tsx payload is wrong. Aborting."
say "10 payloads decoded and verified."

# ---- backups ----
mkdir -p "$BAKDIR/$STAMP"
for f in "${MOD[@]}"; do cp "$f" "$BAKDIR/$STAMP/$(bname "$f")"; done
for f in "${ADD[@]}"; do if [ -f "$f" ]; then cp "$f" "$BAKDIR/$STAMP/$(bname "$f")"; fi; done
say "Backups saved to $BAKDIR/$STAMP/"

rollback() {
  restore_from "$BAKDIR/$STAMP"
  die "$1 All files restored from $BAKDIR/$STAMP."
}

# ---- write ----
i=0; for f in "${ADD[@]}"; do mkdir -p "$(dirname "$f")"; cp "$TMPD/a$i" "$f" || rollback "Could not write $f."; i=$((i+1)); done
i=0; for f in "${MOD[@]}"; do cp "$TMPD/m$i" "$f" || rollback "Could not write $f."; i=$((i+1)); done

i=0; for f in "${ADD[@]}"; do [ "$(sha "$f")" = "${NEW_ADD[$i]}" ] || rollback "$f write verify failed."; i=$((i+1)); done
i=0; for f in "${MOD[@]}"; do [ "$(sha "$f")" = "${NEW_MOD[$i]}" ] || rollback "$f write verify failed."; i=$((i+1)); done

say "Applied Insights and Costs (Part 14e)."
say "Migration 022 runs by itself when the API starts. Nothing to install."
say "Verify before pushing:"
say "  (cd backend && npx tsc --noEmit && npm run build) && (cd frontend && npx tsc --noEmit && npm run build)"
say "  (cd dashboard && npm install && npx tsc --noEmit && npm run build)"
say "Then commit and push rebuild, check the preview, and fast forward main:"
say "  git checkout main && git pull origin main && git merge --ff-only origin/rebuild && git push origin main && git checkout rebuild"
say "Undo: ./vm_insights.sh --revert"
